head.script:
// =============================================================================
/**
 * 문서 인쇄 공통 함수. fil.xml($c.fil)에서 분리.
 * Rexpert 리포트 미리보기 + 상장 외부리포트용 MarkAny(위변조방지) 옵션.
 * (AS-IS: fn_PrintPreView, origin: report.xml)
 * 화면별 변형(fn_PrintPreView_DB / _JLDBNF90002 / _JLDBNF55200 / _JLDINF96000
 * 등)은 본 모듈에 두지 않고 화면 전용으로 관리한다.
 * Rexpert 런타임(rex_GetgoDictionay, rex_gfRexRptOpen)과 외부 화면이 로드되어
 * 있어야 동작한다. 함수명은 camelCase 로 표준화하고 JSDoc 에 AS-IS 원본명을 병기한다.
 *
 * @author Inswave Systems
 * @class print
 * @namespace $c.print
 */
// =============================================================================

scwin.onpageload = function () {

};

/**
 * @method
 * @name printPreView
 * @description 외부 XML 데이터를 연동해 Rexpert 미리보기 팝업을 연다. (MarkAny 위변조방지 적용)
 * (AS-IS: fn_PrintPreView, origin: report.xml)
 * @param {String} rexName 레포트명
 * @param {String} dataType 데이터 타입
 * @param {String} dataLocation 데이터 위치(현재 host 기준 경로)
 * @param {String} dataXPath 데이터 XPath
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.print.printPreView(name, type, loc, xpath);
 */
scwin.printPreView = function (rexName, dataType, dataLocation, dataXPath) {
    // 필수 - rexpert 선언
    const oRptMainParam = rex_GetgoDictionay();
    oRptMainParam.put("rex_rptname", rexName);
    oRptMainParam.put("rex_datatype", dataType);
    oRptMainParam.put("rex_data", "http://" + location.host + dataLocation);
    oRptMainParam.put("rex_xpath", dataXPath);

    // 옵션 - 파라미터 정의
    oRptMainParam.put("test_data", "사용자 정의 파라미터");

    // MarkAny(위변조방지) 옵션 (상장 외부리포트 필수)
    oRptMainParam.put("rex_markany", "true");
    oRptMainParam.put("rex_markany_param", "dllname=MAePageSAFERRexpert.dll;datafilename=MaPrintInfoKrxRex.dat;enablecapture=0;enablespool=0;enableprinter=0;enableprinterInfo=0;printeroption=3;imagesaferoption=0");
    oRptMainParam.put("rex_markany_cellwidth", "16");  // 사이즈 조정
    oRptMainParam.put("rex_markany_cellheight", "2");  // 사이즈 조정
    oRptMainParam.put("rex_markany_path", "http://" + location.host + "/markany/jsp/MaFpsCommon.jsp");
    oRptMainParam.put("rex_markany_setpagedata", "MaPrintInfoKrxRex.dat");

    // 옵션 - 팝업설정
    const rexPreViewFeatures = "center:yes;resizable__no;scroll:no;status:no;dialogWidth:825px;dialogHeight:768px";
    oRptMainParam.put("rex_open_window", rexPreViewFeatures);

    // preview 팝업 열기
    rex_gfRexRptOpen("popup", oRptMainParam);
};
